-- A24: intenção privada de anexo para cliente comprador; não recebe bytes, nome, tipo, URL, documento ou conteúdo.
alter table public.subdivision_buyer_clients add constraint subdivision_buyer_clients_tenant_match unique (id, organization_id);
create table public.subdivision_buyer_attachment_intents (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,buyer_client_id uuid not null,created_by uuid not null references public.identity_subjects(user_id) on delete restrict,created_at timestamptz not null default now(),constraint subdivision_buyer_attachment_intents_client_fk foreign key(buyer_client_id,organization_id) references public.subdivision_buyer_clients(id,organization_id) on delete restrict,constraint subdivision_buyer_attachment_intents_unique unique(organization_id,buyer_client_id));
alter table public.subdivision_buyer_attachment_intents enable row level security;revoke all on table public.subdivision_buyer_attachment_intents from public,anon,authenticated;
comment on table public.subdivision_buyer_attachment_intents is 'A24: intenção privada e opaca; sem arquivo, documento, URL, nome, conteúdo ou download.';
create or replace function public.subdivision_create_buyer_attachment_intent(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_buyer_client_id uuid,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_existing uuid;v_id uuid;begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);select target_id into v_existing from public.admin_audit_events where command_name='subdivision_create_buyer_attachment_intent' and correlation_id=p_correlation_id and outcome='allowed' order by occurred_at desc limit 1;if v_existing is not null then return v_existing;end if;if not exists(select 1 from public.subdivision_buyer_clients where id=p_buyer_client_id and organization_id=p_organization_id)then raise exception using errcode='42501',message='SUBDIVISION_ATTACHMENT_CONTEXT_DENIED';end if;insert into public.subdivision_buyer_attachment_intents(organization_id,buyer_client_id,created_by)values(p_organization_id,p_buyer_client_id,p_actor_user_id)on conflict(organization_id,buyer_client_id)do update set created_by=excluded.created_by returning id into v_id;insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted)values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_create_buyer_attachment_intent','allowed','subdivision_buyer_attachment_intent',v_id,jsonb_build_object('module',p_module::text,'purpose_code',trim(p_purpose_code),'attachment_intent',true));return v_id;end;$$;revoke all on function public.subdivision_create_buyer_attachment_intent(uuid,uuid,public.operating_module,text,uuid,uuid) from public,anon,authenticated;grant execute on function public.subdivision_create_buyer_attachment_intent(uuid,uuid,public.operating_module,text,uuid,uuid) to service_role;
create or replace function public.subdivision_list_buyer_attachment_intents(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(attachment_intent_id uuid,buyer_client_id uuid,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select id,buyer_client_id,created_at from public.subdivision_buyer_attachment_intents where organization_id=p_organization_id order by created_at desc;end;$$;revoke all on function public.subdivision_list_buyer_attachment_intents(uuid,uuid,public.operating_module,text) from public,anon,authenticated;grant execute on function public.subdivision_list_buyer_attachment_intents(uuid,uuid,public.operating_module,text) to service_role;
